import { Injectable } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { Prisma } from '@prisma/client';
import { CreateCategoryDto } from './dto/create-category.dto';

@Injectable()
export class CategoriesService {
  constructor(private prisma: PrismaService) {}

  // ** This servce helps fetch all categories
  async fetchAllCategories() {
    return await this.prisma.category.findMany();
  }

  // ** This servce helps create a category
  async createCategory(data: CreateCategoryDto) {
    try {
      // `id` is generated by the DB — never accept it from the client.
      return await this.prisma.category.create({
        data: {
          name: data.name,
          type: data.type,
          userId: data.userId,
        },
      });
    } catch (error) {
      if (
        error instanceof Prisma.PrismaClientKnownRequestError &&
        error.code === 'P2002'
      ) {
        throw new Error('Category already exists');
      }
      throw error;
    }
  }

  // ** This servce helps update a category
  async updateCategory(id: string, data: CreateCategoryDto) {
    try {
      return await this.prisma.category.update({
        where: { id },
        data: {
          name: data.name,
          type: data.type,
          userId: data.userId,
        },
      });
    } catch (error) {
      if (
        error instanceof Prisma.PrismaClientKnownRequestError &&
        error.code === 'P2002'
      ) {
        throw new Error('Category already exists');
      }
      throw error;
    }
  }

  // ** This servce helps delete a category
  async deleteCategory(id: string) {
    try {
      const category = await this.prisma.category.delete({
        where: { id },
      });
      return `Category ${category.name} deleted`;
    } catch (error) {
      if (
        error instanceof Prisma.PrismaClientKnownRequestError &&
        error.code === 'P2002'
      ) {
        throw new Error('Category not found');
      }
      throw error;
    }
  }
}
